  ('system-breach-clear', 'Mainframe libéré', 'Termine System Breach.', 'trophy', (select id from public.games where slug = 'system-breach'), 10),
  ('system-breach-flawless', 'Sans une égratignure', 'Termine System Breach depuis le secteur 01 sans perdre une seule vie.', 'shield', (select id from public.games where slug = 'system-breach'), 11),
  ('system-breach-5k', 'Hacker d''élite', 'Atteins 5 000 points dans une partie de System Breach.', 'flame', (select id from public.games where slug = 'system-breach'), 12)
